INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_PATRISTIC_LATE','Late Patristic Period',450,750)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_QUASTEN_PATROLOGY','secondary scholarship','Johannes Quasten, Patrology, 4 vols. (Spectrum / Christian Classics, 1950-1986)','Standard reference survey of the Church Fathers: their lives, works, and doctrine, from the Apostolic Fathers through the Latin and Greek patristic Doctors.'),
 ('SRC_FARMER_SAINTS','secondary scholarship','David Hugh Farmer, The Oxford Dictionary of Saints (Oxford University Press, 5th ed. 2011)','REUSE (already in DB): biographical entries and cult/feast data for canonized Fathers.'),
 ('SRC_IRENAEUS_AH','heresiological source','Irenaeus of Lyons, Adversus Haereses (Against Heresies), c. 180 CE; ed. Rousseau & Doutreleau, SC 263-264, 293-294, 210-211 (Cerf, 1979-2002)','REUSE (already in DB): Irenaeus''s own major work, attesting his authorship and anti-Gnostic polemic.')
INSERT INTO _e VALUES
 ('ENT_PAT_CHURCH_FATHERS','The Church Fathers','Collective / hub','Collective / hub','Christian','Patristic theology; doctrine; ecclesiastical authority','B','Collective hub for the Patristic Doctors and Apostolic Fathers (c. 1st-8th c.); a standard category in Christian tradition (Quasten''s Patrology), not a single historical person.'),
 ('ENT_PAT_AUGUSTINE','Augustine of Hippo','Church Father / Doctor','Church Father / Doctor','Christian','Grace; original sin; Trinitarian theology; philosophy of history','B','Bishop of Hippo (354-430), one of the four Latin Doctors; attested by his own Confessions and City of God and by Possidius''s Vita.'),
 ('ENT_PAT_JEROME','Jerome of Stridon','Church Father / Doctor','Church Father / Doctor','Christian','Scripture translation (Vulgate); biblical exegesis; asceticism','B','Priest and scholar (c. 347-420), one of the four Latin Doctors; attested by his own letters and prefaces and by Gennadius.'),
 ('ENT_PAT_AMBROSE','Ambrose of Milan','Church Father / Doctor','Church Father / Doctor','Christian','Hymnody; ecclesiology; anti-Arian polemic; episcopal authority','B','Bishop of Milan (c. 339-397), one of the four Latin Doctors; baptizer of Augustine, attested by Paulinus''s Vita.'),
 ('ENT_PAT_GREGORY_GREAT','Gregory the Great','Church Father / Doctor / Pope','Church Father / Doctor / Pope','Christian','Pastoral theology; liturgy; monasticism; mission','B','Pope Gregory I (c. 540-604), one of the four Latin Doctors; attested by his own letters, Dialogues, and Pastoral Rule.'),
 ('ENT_PAT_ORIGEN','Origen of Alexandria','Church Father / theologian','Church Father / theologian','Christian','Biblical exegesis; allegory; speculative theology; the Hexapla','B','Alexandrian exegete (c. 184-253); foundational but later partly condemned, attested by Eusebius''s Ecclesiastical History and his own surviving works.'),
 ('ENT_PAT_IRENAEUS','Irenaeus of Lyons','Church Father / Doctor','Church Father / Doctor','Christian','Anti-Gnostic polemic; apostolic succession; recapitulation theology','B','Bishop of Lyons (c. 130-202); author of Against Heresies, attested by that work and by Eusebius.'),
 ('ENT_PAT_TERTULLIAN','Tertullian','Church Father / theologian','Church Father / theologian','Christian','Latin theological vocabulary (Trinitas); apologetics; rigorism','B','Carthaginian writer (c. 155-220), first major Latin Christian author; later a Montanist, attested by his own corpus and by Jerome.'),
 ('ENT_PAT_CYPRIAN','Cyprian of Carthage','Church Father','Church Father','Christian','Ecclesiology; unity of the Church; the lapsed; martyrdom','B','Bishop of Carthage (c. 210-258), martyr; attested by his own letters and treatises and by the Acta proconsularia.'),
 ('ENT_PAT_JUSTIN_MARTYR','Justin Martyr','Church Father / apologist','Church Father / apologist','Christian','Apologetics; the Logos doctrine; engagement with philosophy','B','Greek apologist (c. 100-165), martyr; attested by his First and Second Apologies, the Dialogue with Trypho, and the Acts of his martyrdom.'),
 ('ENT_PAT_CLEMENT_ALEX','Clement of Alexandria','Church Father / theologian','Church Father / theologian','Christian','Christian philosophy; catechesis; the true gnosis','B','Titus Flavius Clemens (c. 150-215), head of the Alexandrian catechetical school; attested by his Protrepticus, Paedagogus, and Stromata and by Eusebius.'),
 ('ENT_PAT_CLEMENT_ROME','Clement of Rome','Apostolic Father / Pope','Apostolic Father / Pope','Christian','Church order; concord; early Roman primacy','C','Bishop of Rome (late 1st c.), an Apostolic Father; attested chiefly by the First Epistle of Clement (1 Clement) and by later episcopal lists.'),
 ('ENT_PAT_IGNATIUS_ANTIOCH','Ignatius of Antioch','Apostolic Father','Apostolic Father','Christian','Episcopacy; Eucharist; martyrdom; church unity','C','Bishop of Antioch (d. c. 108), an Apostolic Father and martyr; attested by his seven authentic letters written en route to martyrdom in Rome.'),
 ('ENT_PAT_POLYCARP','Polycarp of Smyrna','Apostolic Father','Apostolic Father','Christian','Apostolic transmission; martyrdom; pastoral exhortation','C','Bishop of Smyrna (c. 69-155), an Apostolic Father, disciple of John; attested by his Letter to the Philippians and the Martyrdom of Polycarp.'),
 ('ENT_PAT_HILARY_POITIERS','Hilary of Poitiers','Church Father / Doctor','Church Father / Doctor','Christian','Anti-Arian Trinitarian theology; Latin defense of Nicaea','B','Bishop of Poitiers (c. 310-367), Doctor of the Church, called ''the Athanasius of the West''; attested by his De Trinitate and by Jerome.'),
 ('ENT_PAT_LEO_GREAT','Leo the Great','Church Father / Doctor / Pope','Church Father / Doctor / Pope','Christian','Christology (the Tome); papal primacy; preaching','B','Pope Leo I (c. 400-461), Doctor of the Church; his Tome shaped the Council of Chalcedon (451), attested by his letters and sermons.'),
 ('ENT_PAT_JOHN_DAMASCUS','John of Damascus','Church Father / Doctor','Church Father / Doctor','Christian','Dogmatic synthesis; defense of icons; systematics','B','Damascene monk and theologian (c. 675-749), Doctor of the Church, traditionally the last of the Greek Fathers; author of the Fount of Knowledge and the Apologies against the iconoclasts.'),
 ('ENT_PAT_BEDE','Bede the Venerable','Church Father / Doctor','Church Father / Doctor','Christian','Ecclesiastical history; exegesis; chronology (computus)','B','Northumbrian monk (c. 673-735), Doctor of the Church; author of the Ecclesiastical History of the English People, attested by his own works and autobiographical note.'),
 ('ENT_PAT_ISIDORE_SEVILLE','Isidore of Seville','Church Father / Doctor','Church Father / Doctor','Christian','Encyclopedic learning (Etymologiae); transmission of patristic heritage','B','Bishop of Seville (c. 560-636), Doctor of the Church, often called the last of the Latin Fathers; author of the Etymologiae.'),
 ('ENT_PAT_GREGORY_NYSSA','Gregory of Nyssa','Church Father / Cappadocian','Church Father / Cappadocian','Christian','Trinitarian theology; mystical theology; apophaticism','B','Bishop of Nyssa (c. 335-395), one of the three Cappadocian Fathers, younger brother of Basil; attested by his theological and ascetical corpus. Distinct from existing Gregory the Theologian (Nazianzen) and Gregory Palamas in the DB.'),
 ('ENT_PAT_CYRIL_ALEX','Cyril of Alexandria','Church Father / Doctor','Church Father / Doctor','Christian','Christology; the Theotokos title; anti-Nestorian polemic','B','Patriarch of Alexandria (c. 376-444), Doctor of the Church; leading figure at the Council of Ephesus (431), attested by his letters and dogmatic works. Distinct from existing Cyril and Methodius in the DB.'),
 ('ENT_PAT_MAXIMUS_CONFESSOR','Maximus the Confessor','Church Father / theologian','Church Father / theologian','Christian','Christology (two wills); cosmic theology; the spiritual life','B','Byzantine monk and theologian (c. 580-662), opponent of Monothelitism; attested by his own extensive corpus and the Acts of his trial.');
