INSERT INTO _p VALUES
 ('ENT_PAT_CHURCH_FATHERS','PER_PATRISTIC','Collective hub for the Patristic Doctors and Apostolic Fathers (c. 1st-8th c.); a standard category in Christian tradition (Quasten''s Patrology), not a single historical person.'),
 ('ENT_PAT_AUGUSTINE','PER_PATRISTIC','Bishop of Hippo (354-430), one of the four Latin Doctors; attested by his own Confessions and City of God and by Possidius''s Vita.'),
 ('ENT_PAT_JEROME','PER_PATRISTIC','Priest and scholar (c. 347-420), one of the four Latin Doctors; attested by his own letters and prefaces and by Gennadius.'),
 ('ENT_PAT_AMBROSE','PER_PATRISTIC','Bishop of Milan (c. 339-397), one of the four Latin Doctors; baptizer of Augustine, attested by Paulinus''s Vita.'),
 ('ENT_PAT_GREGORY_GREAT','PER_PATRISTIC_LATE','Pope Gregory I (c. 540-604), one of the four Latin Doctors; attested by his own letters, Dialogues, and Pastoral Rule.'),
 ('ENT_PAT_ORIGEN','PER_PATRISTIC','Alexandrian exegete (c. 184-253); foundational but later partly condemned, attested by Eusebius''s Ecclesiastical History and his own surviving works.'),
 ('ENT_PAT_IRENAEUS','PER_PATRISTIC','Bishop of Lyons (c. 130-202); author of Against Heresies, attested by that work and by Eusebius.'),
 ('ENT_PAT_TERTULLIAN','PER_PATRISTIC','Carthaginian writer (c. 155-220), first major Latin Christian author; later a Montanist, attested by his own corpus and by Jerome.'),
 ('ENT_PAT_CYPRIAN','PER_PATRISTIC','Bishop of Carthage (c. 210-258), martyr; attested by his own letters and treatises and by the Acta proconsularia.'),
 ('ENT_PAT_JUSTIN_MARTYR','PER_PATRISTIC','Greek apologist (c. 100-165), martyr; attested by his First and Second Apologies, the Dialogue with Trypho, and the Acts of his martyrdom.'),
 ('ENT_PAT_CLEMENT_ALEX','PER_PATRISTIC','Titus Flavius Clemens (c. 150-215), head of the Alexandrian catechetical school; attested by his Protrepticus, Paedagogus, and Stromata and by Eusebius.'),
 ('ENT_PAT_CLEMENT_ROME','PER_APOSTOLIC','Bishop of Rome (late 1st c.), an Apostolic Father; attested chiefly by the First Epistle of Clement (1 Clement) and by later episcopal lists.'),
 ('ENT_PAT_IGNATIUS_ANTIOCH','PER_APOSTOLIC','Bishop of Antioch (d. c. 108), an Apostolic Father and martyr; attested by his seven authentic letters written en route to martyrdom in Rome.'),
 ('ENT_PAT_POLYCARP','PER_APOSTOLIC','Bishop of Smyrna (c. 69-155), an Apostolic Father, disciple of John; attested by his Letter to the Philippians and the Martyrdom of Polycarp.'),
