INSERT INTO _r VALUES
 ('ENT_PAT_AUGUSTINE','member_of','ENT_PAT_CHURCH_FATHERS','high','Augustine of Hippo is one of the four traditional Latin Doctors and a paradigmatic Church Father.'),
 ('ENT_PAT_JEROME','member_of','ENT_PAT_CHURCH_FATHERS','high','Jerome is one of the four traditional Latin Doctors of the Church.'),
 ('ENT_PAT_AMBROSE','member_of','ENT_PAT_CHURCH_FATHERS','high','Ambrose of Milan is one of the four traditional Latin Doctors of the Church.'),
 ('ENT_PAT_GREGORY_GREAT','member_of','ENT_PAT_CHURCH_FATHERS','high','Gregory the Great is the last of the four traditional Latin Doctors of the Church.'),
 ('ENT_PAT_ORIGEN','member_of','ENT_PAT_CHURCH_FATHERS','high','Origen is a foundational early patristic theologian, conventionally grouped among the Church Fathers.'),
 ('ENT_PAT_IRENAEUS','member_of','ENT_PAT_CHURCH_FATHERS','high','Irenaeus of Lyons is a major 2nd-century Church Father.'),
 ('ENT_PAT_TERTULLIAN','member_of','ENT_PAT_CHURCH_FATHERS','high','Tertullian is the first major Latin Father, conventionally grouped among the Church Fathers.'),
 ('ENT_PAT_CYPRIAN','member_of','ENT_PAT_CHURCH_FATHERS','high','Cyprian of Carthage is a 3rd-century Latin Church Father.'),
 ('ENT_PAT_JUSTIN_MARTYR','member_of','ENT_PAT_CHURCH_FATHERS','high','Justin Martyr is the foremost 2nd-century Greek apologist, counted among the Church Fathers.'),
 ('ENT_PAT_CLEMENT_ALEX','member_of','ENT_PAT_CHURCH_FATHERS','high','Clement of Alexandria is an early Alexandrian Church Father.'),
 ('ENT_PAT_CLEMENT_ROME','member_of','ENT_PAT_CHURCH_FATHERS','high','Clement of Rome is one of the Apostolic Fathers, the earliest stratum of the Church Fathers.'),
 ('ENT_PAT_IGNATIUS_ANTIOCH','member_of','ENT_PAT_CHURCH_FATHERS','high','Ignatius of Antioch is one of the Apostolic Fathers.'),
 ('ENT_PAT_POLYCARP','member_of','ENT_PAT_CHURCH_FATHERS','high','Polycarp of Smyrna is one of the Apostolic Fathers.'),
 ('ENT_PAT_HILARY_POITIERS','member_of','ENT_PAT_CHURCH_FATHERS','high','Hilary of Poitiers is a Latin Doctor and Church Father.'),
 ('ENT_PAT_LEO_GREAT','member_of','ENT_PAT_CHURCH_FATHERS','high','Leo the Great is a Doctor of the Church and a patristic Father.'),
 ('ENT_PAT_JOHN_DAMASCUS','member_of','ENT_PAT_CHURCH_FATHERS','high','John of Damascus is traditionally counted as the last of the Greek Church Fathers.'),
 ('ENT_PAT_BEDE','member_of','ENT_PAT_CHURCH_FATHERS','medium','Bede is a Doctor of the Church often grouped with the late Latin Fathers.'),
 ('ENT_PAT_ISIDORE_SEVILLE','member_of','ENT_PAT_CHURCH_FATHERS','high','Isidore of Seville is a Doctor of the Church, frequently called the last of the Latin Fathers.'),
 ('ENT_PAT_GREGORY_NYSSA','member_of','ENT_PAT_CHURCH_FATHERS','high','Gregory of Nyssa is one of the three Cappadocian Fathers.'),
 ('ENT_PAT_CYRIL_ALEX','member_of','ENT_PAT_CHURCH_FATHERS','high','Cyril of Alexandria is a Doctor of the Church and Greek Father.'),
 ('ENT_PAT_MAXIMUS_CONFESSOR','member_of','ENT_PAT_CHURCH_FATHERS','high','Maximus the Confessor is a foundational late Greek/Byzantine Father.'),
 ('ENT_ORTH_ATHANASIUS','member_of','ENT_PAT_CHURCH_FATHERS','high','Cross-link to existing entity: Athanasius of Alexandria is one of the four great Greek Doctors and Church Fathers.'),
 ('ENT_ORTH_BASIL','member_of','ENT_PAT_CHURCH_FATHERS','high','Cross-link to existing entity: Basil the Great is a Cappadocian Father and one of the four great Greek Doctors.'),
 ('ENT_ORTH_GREGORY_THEOLOGIAN','member_of','ENT_PAT_CHURCH_FATHERS','high','Cross-link to existing entity: Gregory the Theologian (Nazianzen) is a Cappadocian Father and one of the four great Greek Doctors.'),
 ('ENT_ORTH_CHRYSOSTOM','member_of','ENT_PAT_CHURCH_FATHERS','high','Cross-link to existing entity: John Chrysostom is one of the four great Greek Doctors and Church Fathers.'),
 ('ENT_PAT_AUGUSTINE','taught_by','ENT_PAT_AMBROSE','high','Augustine was catechized and baptized by Ambrose of Milan, whose preaching he credits in the Confessions with his conversion.'),
 ('ENT_PAT_ORIGEN','taught_by','ENT_PAT_CLEMENT_ALEX','medium','Origen is traditionally held to have studied under Clement of Alexandria at the Alexandrian catechetical school (succession reported by Eusebius).'),
 ('ENT_PAT_IRENAEUS','taught_by','ENT_PAT_POLYCARP','high','Irenaeus reports in his letter to Florinus that he heard Polycarp of Smyrna in his youth, linking him to the apostolic generation.'),
 ('ENT_PAT_GREGORY_NYSSA','sibling_of','ENT_ORTH_BASIL','high','Gregory of Nyssa was the younger brother of Basil the Great; both were Cappadocian Fathers.'),
 ('ENT_PAT_GREGORY_NYSSA','associated_with','ENT_ORTH_GREGORY_THEOLOGIAN','high','Gregory of Nyssa, Basil, and Gregory the Theologian (Nazianzen) form the three Cappadocian Fathers who jointly developed pro-Nicene Trinitarian theology.'),
 ('ENT_PAT_HILARY_POITIERS','associated_with','ENT_ORTH_ATHANASIUS','medium','Hilary of Poitiers was called ''the Athanasius of the West'' for leading the Latin defense of Nicene orthodoxy against Arianism, paralleling Athanasius in the East.'),
 ('ENT_PAT_GREGORY_GREAT','reception_of','ENT_PAT_AUGUSTINE','medium','Gregory the Great''s pastoral and grace theology drew on, and transmitted to the medieval West, the doctrine of Augustine of Hippo.'),
 ('ENT_PAT_JOHN_DAMASCUS','reception_of','ENT_PAT_MAXIMUS_CONFESSOR','medium','John of Damascus''s dogmatic synthesis (the Fount of Knowledge) systematized earlier Greek patristic theology, notably the Christology of Maximus the Confessor.'),
 ('ENT_PAT_CYRIL_ALEX','reception_of','ENT_ORTH_ATHANASIUS','medium','Cyril of Alexandria self-consciously continued the Alexandrian Christological and anti-heretical tradition of his predecessor in the see, Athanasius.'),
 ('ENT_PAT_BEDE','reception_of','ENT_PAT_GREGORY_GREAT','high','Bede''s Ecclesiastical History venerates and depends on Gregory the Great, who initiated the Gregorian mission that converted Bede''s English church.'),
 ('ENT_PAT_ISIDORE_SEVILLE','reception_of','ENT_PAT_AUGUSTINE','medium','Isidore of Seville''s encyclopedic and theological works compile and transmit the Latin patristic heritage, especially Augustine.'),
 ('ENT_PAT_AUGUSTINE','opposes','ENT_MANICH_MANI','medium','Augustine, a former Manichaean auditor, became a leading opponent of Manichaeism, attacking Mani''s system in Contra Faustum and other works. Object verified as ENT_MANICH_MANI.'),
 ('ENT_PAT_AUGUSTINE','reception_of','ENT_PAT_AMBROSE','medium','Beyond baptism, Augustine''s exegetical method and Trinitarian thought were decisively shaped by Ambrose''s allegorical preaching, as he records in the Confessions.');
